def _find_repo_root() -> Path:
    current = Path(__file__).resolve()
    for parent in current.parents:
        if (parent / "frontend" / "src").is_dir() and (parent / "backend" / "src").is_dir():
            return parent
    raise RuntimeError(f"Could not locate repository root from {__file__}")


def _artifact(
    artifact_id: str,
    *,
    role: SourceArtifactRole,
    artifact_format: SourceArtifactFormat,
    display_name: str,
    md5sum: str | None = None,
    parent_artifact_id: str | None = None,
) -> SourceArtifact:
    return SourceArtifact(
        provider="literature_archive",
        artifact_id=artifact_id,
        role=role,
        artifact_format=artifact_format,
        status=SourceArtifactStatus.AVAILABLE,
        reference_id="101",
        reference_curie="REF:101",
        display_name=display_name,
        md5sum=md5sum,
        parent_artifact_id=parent_artifact_id,
        access_policy=SourceAccessPolicy(scope=SourceAccessScope.RESTRICTED, group_ids=("DEMO",)),
    )


