def _capture_stage_record_metadata(
    entries: list[_Entry],
    *,
    stage_name: str,
    message: str,
) -> dict[str, Any]:
    """Capture the exact outer job metadata written by ``supplement_wait._Stage.record``."""

    captured: dict[str, Any] = {JOB_KIND_KEY: SUPPLEMENT_WAIT_JOB_KIND}

    def fake_update_progress(*, metadata: dict[str, Any] | None = None, **_kwargs: Any) -> None:
        if metadata:
            captured.update(metadata)

    with (
        patch.object(
            supplement_wait,
            "get_document_supplement_wait_timeout_seconds",
            return_value=WAIT_TIMEOUT_SECONDS,
        ),
        patch.object(pdf_job_service, "update_progress", side_effect=fake_update_progress),
    ):
        stage = _Stage(
            job_id=str(JOB_UUID),
            plan=_sample_plan(),
            main_ready_at=MAIN_READY_EPOCH,
            clock=lambda: OBSERVED_AT_EPOCH,
        )
        for entry in entries:
            stage.entries[entry.provider_file_id] = entry
        asyncio.run(stage.record(stage_name, message))
    return captured


class _FakeJobRowSession:
    """Minimal session double for ``pdf_job_service`` job-row writers."""

    def __init__(self, job: SimpleNamespace) -> None:
        self._job = job

    def execute(self, _statement: Any) -> Any:
        return SimpleNamespace(scalar_one_or_none=lambda: self._job)

    def flush(self) -> None:
        pass

    def commit(self) -> None:
        pass

    def rollback(self) -> None:
        pass

    def refresh(self, _obj: Any) -> None:
        pass

    def close(self) -> None:
        pass


class _FixedDatetime(datetime):
    @classmethod
    def now(cls, tz: Any = None) -> datetime:
        fixed = datetime(2026, 11, 24, 15, 5, 0, tzinfo=timezone.utc)
        return fixed if tz is None else fixed.astimezone(tz)


